Q() { docker exec -i xnova-database psql -U postgres -d postgres -At -c "$1" < /dev/null; }
echo "== version"; Q "select version()"
echo "== guarded fn args"
Q "select p.oid::regprocedure, pg_get_function_identity_arguments(p.oid), p.prosecdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_market_listing','purchase_market_listing','fulfill_buy_offer','galaxy_navigate','purchase_supply_box','launch_missiles','deploy_to_fortress','create_colony_listing','purchase_colony_listing','secure_abandon_colony','secure_demolish_building','update_production_percentages','refill_colony_resources','purchase_instant_unit','purchase_ship_blueprint','secure_add_to_building_queue','secure_add_to_shipyard_queue','secure_start_research','set_planet_autopilot_enabled','secure_activate_building_queue','use_jump_gate','process_fleet_arrival','process_acs_fleet_arrival','perform_combat','perform_acs_combat','validate_fleet_mission','join_acs_with_fleet','user_can_build_ship','enforce_ship_blueprint_requirement','secure_send_fleet','simulate_xnova_combat','battle_units_diff','format_unit_report','check_moon_creation','contribute_to_jackpot','record_admin_revenue','_internal_set_fxu_context','get_live_tung_price_usd','apply_vip_time_bonus','get_game_speed','_colony_listed_since','fleet_calc_distance','fleet_calc_slowest_speed','fleet_calc_flight_time','fleet_calc_fuel','sync_planet_resources','validate_defense_requirements','validate_ship_requirements','is_user_plus','get_user_daily_mission_speed_bonus') order by 1"
echo "== first BEGIN check (text before first BEGIN in body)"
Q "select p.oid::regprocedure || ' | ' || replace(substr(p.prosrc,1,position('BEGIN' in p.prosrc)+5), chr(10), ' ') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_market_listing','purchase_market_listing','fulfill_buy_offer','galaxy_navigate','purchase_supply_box','launch_missiles','deploy_to_fortress','create_colony_listing','purchase_colony_listing','secure_abandon_colony','secure_demolish_building','update_production_percentages','refill_colony_resources','purchase_instant_unit','purchase_ship_blueprint') order by 1" | cut -c1-900
echo "== funcs selecting random ship types"
Q "select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosrc ilike '%from ship_types%' and p.prosrc ilike '%random()%' order by 1"
echo "== funcs iterating all ship_types (no where code)"
Q "select p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosrc ~* 'from (public\.)?ship_types( st| s)?\s*(order|;|\))' order by 1"
echo "== shipyard_queue cols"; Q "select string_agg(column_name||':'||data_type, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='shipyard_queue'"
echo "== building_queue cols"; Q "select string_agg(column_name||':'||data_type, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='building_queue'"
echo "== fleets cols"; Q "select string_agg(column_name||':'||data_type||':'||coalesce(column_default,''), ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='fleets'"
echo "== referral_commissions cols"; Q "select string_agg(column_name||':'||data_type||':'||is_nullable, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='referral_commissions'"
echo "== triggers building/shipyard/research/user_technologies"
Q "select tgrelid::regclass||' '||tgname||' '||pg_get_triggerdef(oid) from pg_trigger where not tgisinternal and tgrelid::regclass::text in ('building_queue','shipyard_queue','research_queue','user_technologies','planet_buildings') order by 1"
echo "== tables like research"; Q "select table_name from information_schema.tables where table_schema='public' and table_name ilike '%research%'"
echo "== cancel listings fn"; Q "select prosrc from pg_proc where proname='cancel_market_listings_on_planet_loss'"
echo "== _bs_settle"; Q "select prosrc from pg_proc where proname='_bs_settle'"
echo "== cron"; Q "select jobname, schedule, command from cron.job order by 1"
